CREATE TABLE university_records (id UUID PRIMARY KEY, student_id VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, major VARCHAR(120) NOT NULL, enrolled_since DATE NOT NULL, status VARCHAR(32) NOT NULL, outlook_groups TEXT[] NOT NULL DEFAULT '{}', courses TEXT[] NOT NULL DEFAULT '{}', fcim_messages TEXT[] NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
